style.css:
@-moz-document domain("youtube.com") {
/* =======================================================
       FINAL TRACK REFIX: SEAMLESS MATHEMATICAL CODE GRADIENT
       ======================================================= */
    
    /* 1. THE DOT: Replaces the moving handle with your character image */
    .ytp-scrubber-button {
        background: url("https://i.postimg.cc/Jz9ng3zg/Untitled317-20260727202138.png") no-repeat center !important;
        background-size: contain !important;
        width: 34px !important;   
        height: 34px !important;  
        border: none !important;
        box-shadow: none !important;
        transform: translateY(-4px) !important;
        z-index: 100 !important;
    }

    .ytp-scrubber-button.ytp-swatch-background-color {
        background-color: transparent !important;
    }

    /* 2. THE BAR: Generates a flawless flat blue gradient matching your reference look */
    .ytp-play-progress.ytp-swatch-background-color {
            background: linear-gradient(180deg, #00072d 0%, #00072d 25%, #001c55 25%, #001c55 50%, #0a2472 50%, #0a2472 75%, #ede580 75%, #ede580 100%) !important;
        z-index: 10 !important;
    }

    /* 3. THE UNPLAYED RAIL: Clean solid dark gray background for the unwatched track */
    .ytp-progress-list {
        background: #1c1c1c !important; 
        z-index: 1 !important;
    }

    /* 4. THE RAIL FORCING: Forces all inner layers to stay thick so your image shows clearly */
    .ytp-chrome-controls .ytp-progress-bar-container,
    .ytp-progress-bar,
    .ytp-progress-list,
    .ytp-play-progress,
    .ytp-hover-progress-list,
    .ytp-load-progress {
        height: 18px !important;
    }
}
